<script setup>
import { computed, reactive, ref } from 'vue';
import Icon from '../components/Icon.vue'; import Modal from '../components/Modal.vue';
import { data, byId, saveRecord, deleteRecord, notify } from '../store.js';
import { weekdays } from '../format.js';
const filter = ref(''), editing = ref(false), form = reactive({}), targetType = ref('level'), saving = ref(false), error = ref('');
const rows = computed(() => data.permissions.filter(p => !filter.value || String(p.accessLevelId) === filter.value));
function edit(rule) { Object.keys(form).forEach(k => delete form[k]); targetType.value = rule?.employeeId ? 'employee' : 'level'; Object.assign(form, rule ? { ...rule, days: [...(rule.days || [])], validFrom: rule.validFrom || '', validTo: rule.validTo || '' } : { accessLevelId: data.access_levels[0]?.id || '', employeeId: '', roomId: data.rooms[0]?.id || '', days: [1, 2, 3, 4, 5], startTime: '08:00', endTime: '20:00', validFrom: '', validTo: '', active: true }); editing.value = true; error.value = ''; }
async function submit() {
  saving.value = true; error.value = '';
  try {
    if (!form.days.length) throw new Error('Выберите хотя бы один день недели.');
    if (form.validFrom && form.validTo && form.validFrom > form.validTo) throw new Error('Дата окончания должна быть не раньше даты начала.');
    await saveRecord('permissions', { ...form, employeeId: targetType.value === 'employee' ? form.employeeId : null, accessLevelId: targetType.value === 'level' ? form.accessLevelId : null, validFrom: form.validFrom || null, validTo: form.validTo || null }); editing.value = false; notify('Разрешение сохранено.');
  } catch (e) { error.value = e.message; } finally { saving.value = false; }
}
async function remove(rule) { if (!confirm('Удалить разрешение? История проходов сохранится.')) return; try { await deleteRecord('permissions', rule.id); notify('Разрешение удалено.'); } catch (e) { notify(e.message, 'error'); } }
async function toggle(rule) { try { await saveRecord('permissions', { id: rule.id, active: rule.active === false }); notify(rule.active === false ? 'Разрешение включено.' : 'Разрешение приостановлено.'); } catch (e) { notify(e.message, 'error'); } }
const daysText = days => !days?.length || days.length === 7 ? 'Ежедневно' : weekdays.filter(d => days.includes(d.value)).map(d => d.label).join(', ');
</script>
<template><div class="page-header"><div><span class="eyebrow">ПОЛИТИКА ДОСТУПА</span><h1>Права доступа<span class="heading-dot">.</span></h1><p>Разрешения для уровней доступа и отдельных сотрудников.</p></div><button class="button primary" @click="edit()"><Icon name="plus" :size="18" />Добавить разрешение</button></div><div class="levels-strip"><article v-for="level in data.access_levels" :key="level.id"><span class="stat-icon green"><Icon name="key" :size="19" /></span><div><strong>{{ level.name }}</strong><p>{{ level.description || 'Уровень доступа' }}</p></div><span class="counter">{{ data.permissions.filter(p => String(p.accessLevelId) === String(level.id)).length }}</span></article></div><div class="toolbar"><select v-model="filter" aria-label="Уровень доступа"><option value="">Все уровни доступа</option><option v-for="level in data.access_levels" :key="level.id" :value="String(level.id)">{{ level.name }}</option></select><span class="toolbar-count">{{ rows.length }} разрешений</span></div><section class="panel"><div v-if="!rows.length" class="empty-state"><Icon name="key" :size="36" /><h3>Разрешений нет</h3><p>Создайте разрешение для сотрудника или уровня доступа.</p></div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Кому разрешено</th><th>Помещение</th><th>Дни и время</th><th>Период действия</th><th>Статус</th><th></th></tr></thead><tbody><tr v-for="rule in rows" :key="rule.id"><td><strong class="cell-main">{{ rule.employeeId ? byId('employees', rule.employeeId)?.fullName : byId('access_levels', rule.accessLevelId)?.name }}</strong><small class="cell-sub">{{ rule.employeeId ? 'Индивидуальное разрешение' : 'Уровень доступа' }}</small></td><td>{{ byId('rooms', rule.roomId)?.name || '—' }}</td><td><strong class="cell-main mono">{{ rule.startTime || '00:00' }} — {{ rule.endTime || '23:59' }}</strong><small class="cell-sub">{{ daysText(rule.days) }}</small></td><td><span v-if="!rule.validFrom && !rule.validTo" class="muted">Без ограничения дат</span><template v-else>{{ rule.validFrom || 'Начало не задано' }}<br />{{ rule.validTo || 'Окончание не задано' }}</template></td><td><button class="badge badge-button" :class="rule.active === false ? 'neutral' : 'green'" :title="rule.active === false ? 'Включить разрешение' : 'Приостановить разрешение'" @click="toggle(rule)"><span class="dot"></span>{{ rule.active === false ? 'Приостановлено' : 'Действует' }}</button></td><td><div class="row-actions"><button class="icon-button" aria-label="Редактировать разрешение" @click="edit(rule)"><Icon name="edit" :size="17" /></button><button class="icon-button danger" aria-label="Удалить разрешение" @click="remove(rule)"><Icon name="trash" :size="17" /></button></div></td></tr></tbody></table></div></section><div class="subtle-note"><Icon name="help" :size="17" /><p>Достаточно одного действующего разрешения. Блокировка сотрудника запрещает вход независимо от разрешений. Время — московское.</p></div><Modal v-if="editing" :title="form.id ? 'Редактировать разрешение' : 'Новое разрешение'" @close="!saving && (editing = false)"><form id="permission-form" class="form-grid" @submit.prevent="submit"><label class="span-2">Назначить разрешение<select v-model="targetType"><option value="level">Уровню доступа</option><option value="employee">Сотруднику индивидуально</option></select></label><label v-if="targetType === 'level'" class="span-2">Уровень доступа<select v-model="form.accessLevelId" required><option value="" disabled>Выберите уровень</option><option v-for="l in data.access_levels" :key="l.id" :value="l.id">{{ l.name }}</option></select></label><label v-else class="span-2">Сотрудник<select v-model="form.employeeId" required><option value="" disabled>Выберите сотрудника</option><option v-for="e in data.employees" :key="e.id" :value="e.id">{{ e.fullName }}</option></select></label><label class="span-2">Помещение<select v-model="form.roomId" required><option value="" disabled>Выберите помещение</option><option v-for="r in data.rooms" :key="r.id" :value="r.id">{{ r.name }}</option></select></label><div class="span-2"><span class="field-label">Дни недели</span><div class="weekday-selector"><label v-for="day in weekdays" :key="day.value" :class="{ selected: form.days.includes(day.value) }"><input v-model="form.days" type="checkbox" :value="day.value" />{{ day.label }}</label></div></div><label>Начало интервала<input v-model="form.startTime" type="time" required /></label><label>Конец интервала<input v-model="form.endTime" type="time" required /></label><p v-if="form.startTime > form.endTime" class="muted span-2">Интервал проходит через полночь. Дни недели относятся к началу смены.</p><label>Действует с<input v-model="form.validFrom" type="date" /></label><label>Действует по<input v-model="form.validTo" type="date" /></label><label class="checkbox-label span-2"><input v-model="form.active" type="checkbox" />Разрешение включено</label><div v-if="error" class="alert-box span-2" role="alert">{{ error }}</div></form><template #footer><button class="button" :disabled="saving" @click="editing = false">Отмена</button><button class="button primary" type="submit" form="permission-form" :disabled="saving">{{ saving ? 'Сохраняем…' : 'Сохранить' }}</button></template></Modal></template>
